/* Generated by tools/gen_anim_timing.py from original animation timing. */
void sh_anim_loop_timing(ShAnimTiming *model, const ShAnimClipTiming *clip,
                         int32_t timestep, ShAnimPoseTiming *pose)
{

    int32_t    startKeyframeIdx;
    int32_t    endKeyframeIdx;
    int32_t    nextStartKeyframeIdx;
    int32_t    keyframeCount;
    int32_t startTime;
    int32_t nextStartTime;
    int32_t duration;
    int32_t newTime;
    int32_t    newKeyframeIdx0;
    int32_t    newKeyframeIdx1;
    int32_t alpha;

    startKeyframeIdx     = clip->first;
    endKeyframeIdx       = clip->last;
    nextStartKeyframeIdx = endKeyframeIdx + 1;
    keyframeCount        = nextStartKeyframeIdx - startKeyframeIdx;

    startTime     = SH_Q12(startKeyframeIdx);
    nextStartTime = SH_Q12(nextStartKeyframeIdx);
    duration      = SH_Q12(keyframeCount);

    
    newTime = model->time + timestep;
    while (newTime < startTime)
    {
        newTime += duration;
    }
    while (newTime >= nextStartTime)
    {
        newTime -= duration;
    }

    
    newKeyframeIdx0 = (newTime >> 12);
    newKeyframeIdx1 = newKeyframeIdx0 + 1;
    if (newKeyframeIdx1 == nextStartKeyframeIdx)
    {
        newKeyframeIdx1 = startKeyframeIdx;
    }

    
    alpha = (newTime & 4095);
    pose->first = newKeyframeIdx0;
    pose->second = newKeyframeIdx1;
    pose->alpha = alpha;

    
    model->time        = newTime;
    model->keyframe = newKeyframeIdx0;
    model->alpha       = SH_Q12(0.0f);
}
void sh_anim_blend_timing(ShAnimTiming *model, const ShAnimClipTiming *clip,
                         int32_t timestep, ShAnimPoseTiming *pose)
{

    bool   setNewAnimStatus;
    int32_t    startKeyframeIdx;
    int32_t    endKeyframeIdx;
    int32_t alpha;

    setNewAnimStatus = false;
    startKeyframeIdx = clip->first;
    endKeyframeIdx   = clip->last;

    
    if (startKeyframeIdx == -1)
    {
        startKeyframeIdx = model->keyframe;
    }

    
    alpha  = model->alpha;
    alpha += timestep;
    if (alpha >= SH_Q12(0.5f))
    {
        model->time = SH_Q12(endKeyframeIdx);
    }
    else
    {
        model->time = SH_Q12(startKeyframeIdx);
    }

    
    if (alpha >= SH_Q12(1.0f))
    {
        startKeyframeIdx            = endKeyframeIdx;
        model->keyframe = endKeyframeIdx;

        alpha            = SH_Q12(0.0f);
        setNewAnimStatus = true;
    }

    
    pose->first = startKeyframeIdx;
    pose->second = endKeyframeIdx;
    pose->alpha = alpha;

    
    model->alpha = alpha;

    
    if (setNewAnimStatus)
    {
        model->status = clip->link;
    }
}
void sh_anim_once_timing(ShAnimTiming *model, const ShAnimClipTiming *clip,
                         int32_t timestep, ShAnimPoseTiming *pose)
{

    bool   setNewAnimStatus;
    int32_t newTime;
    int32_t    newKeyframeIdx;
    int32_t startTime;
    int32_t endTime;
    int32_t alpha;

    setNewAnimStatus = false;

    
    newTime        = model->time;
    newKeyframeIdx = (newTime >> 12);
    if (timestep != SH_Q12(0.0f))
    {
        newTime += timestep;

        
        endTime = SH_Q12(clip->last);
        if (newTime >= endTime)
        {
            newTime          = endTime;
            setNewAnimStatus = true;
        }
        else
        {
            startTime = SH_Q12(clip->first);
            if (newTime <= startTime)
            {
                newTime          = startTime;
                setNewAnimStatus = true;
            }
        }

        newKeyframeIdx = (newTime >> 12);
    }

    
    alpha = (newTime & 4095);
    pose->first = newKeyframeIdx;
    pose->second = newKeyframeIdx + 1;
    pose->alpha = alpha;

    
    model->time        = newTime;
    model->keyframe = newKeyframeIdx;
    model->alpha       = SH_Q12(0.0f);

    
    if (setNewAnimStatus)
    {
        model->status = clip->link;
    }
}
